<?php
namespace App\Http\Controllers;
use App\Models\{InventoryTransaction,Order}; use App\Services\InventoryService; use Illuminate\Support\Facades\DB;
class AdminOrderController { public function index(string $status='pending'){abort_unless(in_array($status,['pending','outgoing','done'],true),404);return view('admin.orders.index',['status'=>$status,'orders'=>Order::with('customer','items.product')->where('status',$status)->latest('order_date')->paginate(12)]);} public function accept(Order $order,InventoryService $i){DB::transaction(function()use($order,$i){$order->load('items.product');abort_unless($order->status==='pending',409);foreach($order->items as $item){if($i->balance($item->product_id)<$item->quantity)abort(422,'Not enough stock for '.$item->product->product_name.'.');}foreach($order->items as $item)InventoryTransaction::create(['product_id'=>$item->product_id,'transaction_type'=>'deduction','quantity'=>$item->quantity,'reason'=>'Customer Order '.$order->order_number,'transaction_date'=>now()->toDateString(),'recorded_by'=>auth()->id(),'remarks'=>'Stock deducted when order was accepted.']);$order->update(['status'=>'outgoing']);});return back()->with('success','Order accepted and moved to Outgoing.');} public function done(Order $order){abort_unless($order->status==='outgoing',409);$order->update(['status'=>'done']);return back()->with('success','Order marked as Done.');} }
